class Solution { public int waysToReachTarget(int target,int[][] types){final int MOD=1_000_000_007;int[] dp=new int[target+1];dp[0]=1;for(int[] type:types){int[] next=new int[target+1];for(int score=0;score<=target;score++)if(dp[score]!=0)for(int take=0;take<=type[0]&&score+take*type[1]<=target;take++){int newScore=score+take*type[1];next[newScore]+=dp[score];if(next[newScore]>=MOD)next[newScore]-=MOD;}dp=next;}return dp[target];} }
